    let result = watch::stop_requested(&watchers, &known, &raw_document_path(&dir, "notes.txt"));

    assert!(matches!(result, Err(DocumentIoError::InvalidPath { .. })));
}

#[test]
fn 通知のパスは監視を依頼した綴りのまま届く() {
    let dir = TempDir::new("watch-normal");
    fs::write(dir.join("document.dcmp"), r#"{"version":1}"#).expect("監視対象を用意できる");
    let known = Arc::new(KnownContentRegistry::new());
    let watchers = DocumentWatchers::new();
    // 正規化すると消える `/./` を綴りに含める
    let raw = raw_document_path(&dir, "./document.dcmp");

    let (started, payloads) = watch_requested_payloads(&watchers, &known, &raw);
    started.expect("監視を開始できる");
    fs::write(dir.join("document.dcmp"), r#"{"version":2}"#).expect("外部からの書き込みができる");
    let payload: serde_json::Value =
        serde_json::from_str(&next_change(&payloads)).expect("ペイロードは JSON");

    assert_eq!(payload["path"], raw.as_str());
}

#[test]
fn 外部がファイルを書き換えると変更が通知される() {
    let dir = TempDir::new("watch-normal");
    let path = document_file_path(&dir, "document.dcmp");
    fs::write(&path, r#"{"version":1}"#).expect("監視対象を用意できる");
    let known = Arc::new(KnownContentRegistry::new());
    let watchers = DocumentWatchers::new();

    let changes = watch_changes(&watchers, &known, &path);
    fs::write(&path, r#"{"version":2}"#).expect("外部からの書き込みができる");

    assert_eq!(next_change(&changes), r#"{"version":2}"#);
}

pub fn parse(raw: &str) -> Result<Self, DocumentIoError> {
    let path = Path::new(raw);
    if !path.is_absolute() {
        return Err(DocumentIoError::invalid_path(path, "絶対パスではない"));
    }
    if path
        .components()
        .any(|component| component == Component::ParentDir)
    {
        return Err(DocumentIoError::invalid_path(path, "`..` の要素を含む"));
    }
    // `file_name()` は末尾の `/` や `/.` を読み飛ばして手前の要素を返すため、
    // 渡された綴りがその名前で終わっていることまで見る。
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .filter(|name| raw.ends_with(name))
        .ok_or_else(|| DocumentIoError::invalid_path(path, "ファイル名で終わらない"))?;
    // NTFS では `name:stream` が代替データストリームを指し、拡張子の検査を通っても
    // 別のファイル(`notes.txt`)へ書き込めてしまう。OS を問わず拒否する。
    if file_name.contains(':') {
        return Err(DocumentIoError::invalid_path(
            path,
            "ファイル名に `:` を含む",
        ));
    }
    let is_dcmp = path
        .extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case("dcmp"));
    if !is_dcmp {
        return Err(DocumentIoError::invalid_path(
            path,
            "拡張子が `.dcmp` ではない",
        ));
    }
    Ok(Self(path.to_path_buf()))
}

#[tauri::command]
pub fn load_document(path: String) -> Result<String, DocumentIoError> {
    let path = DocumentFilePath::parse(&path)?;
    load(&path)
}

